changes.after:
.rad-bladder-examples { margin: 24px 0; }
.rad-bladder-examples .rad-report-actions { margin-bottom: 20px; }
.rad-bladder-examples [aria-pressed="true"] { background: var(--ink); color: var(--paper); }
.rad-bladder-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 24px; }
.rad-bladder-case-grid img { display: block; width: 100%; height: auto; background: #000; cursor: zoom-in; }
.rad-bladder-case-grid figcaption { margin-top: 12px; }
